=== FILE: skid_buffer.v ===
// skid_buffer.v
// Register slice (skid buffer) for one valid/ready stream.
// Implements interface_spec.md and microarchitecture.md (project prj-ba2f05400a).
// Every output is a flop or the inverse of one: no combinational path from
// m_ready, s_valid or s_data to s_ready, m_valid or m_data.
`timescale 1ns / 1ps
`default_nettype none

module skid_buffer #(
    parameter integer WIDTH = 8
) (
    input  wire             clk,
    input  wire             rst_n,
    input  wire             s_valid,
    output wire             s_ready,
    input  wire [WIDTH-1:0] s_data,
    output reg              m_valid,
    input  wire             m_ready,
    output reg  [WIDTH-1:0] m_data
);

    // Skid register: holds the newer of two beats, only while m_valid is high.
    reg             skid_valid;
    reg [WIDTH-1:0] skid_data;

    // Next-state values.
    reg             m_valid_d;
    reg [WIDTH-1:0] m_data_d;
    reg             skid_valid_d;
    reg [WIDTH-1:0] skid_data_d;

    wire m_free;  // the output register may load on this edge
    wire s_fire;  // an upstream beat is accepted on this edge

    assign s_ready = ~skid_valid;
    assign m_free  = ~m_valid | m_ready;
    assign s_fire  = s_valid & ~skid_valid;

    // Next state (microarchitecture.md section 3).
    always @* begin
        m_valid_d    = m_valid;
        m_data_d     = m_data;
        skid_valid_d = skid_valid;
        skid_data_d  = skid_data;
        if (m_free) begin
            if (skid_valid) begin
                // The skid beat is the oldest held: move it to the output.
                m_valid_d    = 1'b1;
                m_data_d     = skid_data;
                skid_valid_d = 1'b0;
            end else begin
                // Output register free and skid empty: take the input.
                m_valid_d    = s_valid;
                m_data_d     = s_data;
            end
        end else if (s_fire) begin
            // Output stalled and a beat accepted: it skids.
            skid_valid_d = 1'b1;
            skid_data_d  = s_data;
        end
    end

    // Control registers: synchronous, active-low reset.
    always @(posedge clk) begin
        if (!rst_n) begin
            m_valid    <= 1'b0;
            skid_valid <= 1'b0;
        end else begin
            m_valid    <= m_valid_d;
            skid_valid <= skid_valid_d;
        end
    end

    // Data registers: not reset (microarchitecture.md section 2).
    always @(posedge clk) begin
        m_data    <= m_data_d;
        skid_data <= skid_data_d;
    end

`ifdef FORMAL
    // Design-intent properties. They are not submitted with a .sby in this task.
    reg f_past_valid;
    initial f_past_valid = 1'b0;
    always @(posedge clk) f_past_valid <= 1'b1;

    always @(*) begin
        if (!f_past_valid) assume (!rst_n);
        if (f_past_valid) assert (!skid_valid || m_valid);
    end

    always @(posedge clk) begin
        if (f_past_valid) begin
            if (!$past(rst_n)) begin
                assert (!m_valid);
                assert (!skid_valid);
            end else begin
                // Hold: a stalled beat stays offered with the same data.
                if ($past(m_valid && !m_ready)) begin
                    assert (m_valid);
                    assert (m_data == $past(m_data));
                end
                // The skid beat holds while the output is stalled.
                if ($past(skid_valid && !m_ready)) begin
                    assert (skid_valid);
                    assert (skid_data == $past(skid_data));
                end
                // Order: the skid beat leaves before any newer beat.
                if ($past(skid_valid && m_ready)) begin
                    assert (m_valid);
                    assert (m_data == $past(skid_data));
                    assert (!skid_valid);
                end
            end
        end
    end

    always @(posedge clk) begin
        if (f_past_valid && rst_n) begin
            cover (skid_valid);                                   // full slice
            cover (m_valid && m_ready && s_valid && s_ready);     // full throughput
            cover ($past(skid_valid) && $past(rst_n) && !skid_valid); // skid drains
        end
    end
`endif

endmodule

`default_nettype wire
=== END FILE ===
