// skid_buffer_tb.v
// Self-checking testbench for skid_buffer, two lanes: WIDTH 8 and WIDTH 1.
// Each lane keeps a reference queue of up to two beats and checks the DUT
// outputs against it every cycle, and checks that s_ready, m_valid and m_data
// do not move when m_ready, s_valid and s_data are flipped inside a cycle.
`timescale 1ns / 1ps
`default_nettype none

`define CHK(c, m) begin if (c) passed = passed + 1; else begin failed = failed + 1; $error("skid_buffer_tb WIDTH=%0d t=%0t: %s", WIDTH, $time, m); end end

module skid_buffer_tb;
    reg clk;
    initial clk = 1'b0;
    always #5 clk = ~clk;

    wire        done8;
    wire        done1;
    wire [31:0] passed8;
    wire [31:0] failed8;
    wire [31:0] passed1;
    wire [31:0] failed1;

    reg [8*64-1:0] nonce;
    reg            reported;
    integer        ok;

    skid_buffer_tb_lane #(.WIDTH(8)) lane8 (
        .clk(clk), .done(done8), .passed(passed8), .failed(failed8)
    );

    skid_buffer_tb_lane #(.WIDTH(1)) lane1 (
        .clk(clk), .done(done1), .passed(passed1), .failed(failed1)
    );

    initial begin
        nonce    = 512'd0;
        reported = 1'b0;
        ok       = $value$plusargs("nirmaan_nonce=%s", nonce);
        wait (done8 === 1'b1 && done1 === 1'b1);
        #1;
        if (!reported) begin
            reported = 1'b1;
            $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce,
                     passed8 + passed1, failed8 + failed1);
            $finish;
        end
    end

    initial begin
        #1000000;
        if (!reported) begin
            reported = 1'b1;
            $error("skid_buffer_tb: timeout before both lanes finished");
            $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce,
                     passed8 + passed1, failed8 + failed1 + 32'd1);
            $finish;
        end
    end
endmodule

module skid_buffer_tb_lane #(
    parameter integer WIDTH = 8
) (
    input  wire        clk,
    output reg         done,
    output reg  [31:0] passed,
    output reg  [31:0] failed
);
    reg              rst_n;
    reg              s_valid;
    reg  [WIDTH-1:0] s_data;
    reg              m_ready;
    wire             s_ready;
    wire             m_valid;
    wire [WIDTH-1:0] m_data;

    skid_buffer #(.WIDTH(WIDTH)) dut (
        .clk     (clk),
        .rst_n   (rst_n),
        .s_valid (s_valid),
        .s_ready (s_ready),
        .s_data  (s_data),
        .m_valid (m_valid),
        .m_ready (m_ready),
        .m_data  (m_data)
    );

    // Reference model and bookkeeping.
    integer          count;    // beats held by the model (0..2)
    integer          acc;      // beats accepted upstream
    integer          del;      // beats delivered downstream
    integer          dropped;  // beats dropped by reset
    integer          a0;
    integer          d0;
    integer          i;
    integer          k;
    reg  [WIDTH-1:0] q0;       // oldest held beat
    reg  [WIDTH-1:0] q1;       // newer held beat
    reg  [WIDTH-1:0] prev_data;
    reg  [WIDTH-1:0] dctr;
    reg              checking;
    reg              prev_stall;
    reg              last_s_fire;
    reg  [31:0]      r;
    reg  [31:0]      pat;
    reg  [7:0]       sv_th;
    reg  [7:0]       mr_th;
    reg  [7:0]       rst_th;

    // One clock cycle. Called just after a falling edge with inputs set;
    // returns just after the next falling edge.
    task step;
        reg             sr0;
        reg             mv0;
        reg [WIDTH-1:0] md0;
        reg             s_fire;
        reg             m_fire;
        begin
            #1;
            if (checking) begin
                `CHK(m_valid === (count != 0), "m_valid must be high exactly while a beat is held")
                `CHK(s_ready === (count < 2), "s_ready must be high exactly while at most one beat is held")
                if (count != 0) `CHK(m_data === q0, "m_data must be the oldest held beat")
                if (prev_stall) begin
                    `CHK(m_valid === 1'b1, "hold: a stalled beat must stay offered")
                    `CHK(m_data === prev_data, "hold: a stalled beat must keep its data")
                end
                // Flip the inputs inside the cycle: no output may follow.
                sr0 = s_ready;
                mv0 = m_valid;
                md0 = m_data;
                m_ready = ~m_ready;
                s_valid = ~s_valid;
                s_data  = ~s_data;
                #1;
                `CHK(s_ready === sr0, "s_ready must not move with m_ready or s_valid inside a cycle")
                `CHK(m_valid === mv0, "m_valid must not move with the inputs inside a cycle")
                `CHK(m_data === md0, "m_data must not move with the inputs inside a cycle")
                m_ready = ~m_ready;
                s_valid = ~s_valid;
                s_data  = ~s_data;
                #1;
            end
            s_fire      = checking && rst_n && s_valid && s_ready;
            m_fire      = checking && rst_n && m_valid && m_ready;
            prev_stall  = checking && rst_n && m_valid && !m_ready;
            prev_data   = m_data;
            last_s_fire = s_fire;
            if (!rst_n) begin
                dropped = dropped + count;
                count   = 0;
            end else if (checking) begin
                if (m_fire) begin
                    del   = del + 1;
                    q0    = q1;
                    count = count - 1;
                end
                if (s_fire) begin
                    acc = acc + 1;
                    if (count == 0) q0 = s_data;
                    else            q1 = s_data;
                    count = count + 1;
                end
            end
            @(posedge clk);
            if (!rst_n) checking = 1'b1;
            @(negedge clk);
        end
    endtask

    task drain;
        begin
            rst_n   = 1'b1;
            s_valid = 1'b0;
            m_ready = 1'b1;
            step;
            step;
            step;
            `CHK(count == 0, "drain: the model must be empty")
            `CHK(m_valid === 1'b0, "drain: m_valid must be low after the drain")
            `CHK(s_ready === 1'b1, "drain: s_ready must be high after the drain")
            `CHK(acc == del + dropped, "drain: every accepted beat delivered once or dropped by reset")
        end
    endtask

    initial begin
        done        = 1'b0;
        passed      = 32'd0;
        failed      = 32'd0;
        count       = 0;
        acc         = 0;
        del         = 0;
        dropped     = 0;
        a0          = 0;
        d0          = 0;
        i           = 0;
        k           = 0;
        q0          = {WIDTH{1'b0}};
        q1          = {WIDTH{1'b0}};
        prev_data   = {WIDTH{1'b0}};
        dctr        = {WIDTH{1'b0}};
        checking    = 1'b0;
        prev_stall  = 1'b0;
        last_s_fire = 1'b0;
        r           = 32'd0;
        pat         = 32'd0;
        sv_th       = 8'd0;
        mr_th       = 8'd0;
        rst_th      = 8'd5;
        rst_n       = 1'b0;
        s_valid     = 1'b0;
        s_data      = {WIDTH{1'b0}};
        m_ready     = 1'b0;
        @(negedge clk);

        // 1. Reset values, with a beat offered during reset.
        s_valid = 1'b1;
        m_ready = 1'b1;
        s_data  = {WIDTH{1'b1}};
        step;
        step;
        `CHK(m_valid === 1'b0, "reset: m_valid must be low")
        `CHK(s_ready === 1'b1, "reset: s_ready must be high")
        rst_n   = 1'b1;
        s_valid = 1'b0;
        step;
        `CHK(m_valid === 1'b0, "reset: no beat offered during reset may appear")
        `CHK(acc == 0, "reset: no beat accepted during reset")

        // 2. One-cycle latency.
        dctr    = dctr + 1'b1;
        s_valid = 1'b1;
        s_data  = dctr;
        m_ready = 1'b1;
        `CHK(m_valid === 1'b0, "latency: nothing offered before the accepting edge")
        step;
        s_valid = 1'b0;
        `CHK(acc == 1, "latency: the beat must be accepted")
        `CHK(m_valid === 1'b1, "latency: the beat must be offered right after its accepting edge")
        `CHK(m_data === dctr, "latency: the offered beat must carry its data")
        step;
        `CHK(del == 1, "latency: the beat must be delivered once")
        `CHK(m_valid === 1'b0, "latency: the slice must be empty after the beat leaves")

        // 3. Full throughput.
        a0      = acc;
        d0      = del;
        m_ready = 1'b1;
        s_valid = 1'b1;
        for (i = 0; i < 64; i = i + 1) begin
            dctr   = dctr + 1'b1;
            s_data = dctr;
            `CHK(s_ready === 1'b1, "throughput: s_ready must stay high")
            if (i > 0) `CHK(m_valid === 1'b1, "throughput: no bubble on the output")
            step;
        end
        `CHK(acc - a0 == 64, "throughput: one beat accepted per edge")
        `CHK(del - d0 == 63, "throughput: one beat delivered per edge")
        s_valid = 1'b0;
        step;
        `CHK(del - d0 == 64, "throughput: every beat delivered")
        `CHK(m_valid === 1'b0, "throughput: the slice must be empty after the stream")

        // 4. Stall with one beat held then two; then release.
        a0      = acc;
        d0      = del;
        m_ready = 1'b0;
        s_valid = 1'b1;
        dctr    = dctr + 1'b1;
        s_data  = dctr;
        step;
        `CHK(acc - a0 == 1, "stall: the first beat must be accepted")
        `CHK(s_ready === 1'b1, "stall: with one beat held s_ready must stay high")
        dctr   = dctr + 1'b1;
        s_data = dctr;
        step;
        `CHK(acc - a0 == 2, "stall: a second beat must be accepted while the output is stalled")
        `CHK(s_ready === 1'b0, "stall: with two beats held s_ready must be low")
        dctr   = dctr + 1'b1;
        s_data = dctr;
        for (i = 0; i < 4; i = i + 1) step;
        `CHK(acc - a0 == 2, "stall: a third beat must not be accepted while full")
        `CHK(del == d0, "stall: nothing may be delivered while m_ready is low")
        m_ready = 1'b1;
        step;
        `CHK(del - d0 == 1, "release: the first beat must leave")
        `CHK(s_ready === 1'b1, "release: s_ready must rise once a beat leaves")
        `CHK(m_valid === 1'b1, "release: the second beat must be offered with no bubble")
        step;
        `CHK(acc - a0 == 3, "release: the third beat must be accepted after s_ready rose")
        `CHK(del - d0 == 2, "release: the second beat must leave")
        s_valid = 1'b0;
        step;
        `CHK(del - d0 == 3, "release: every beat must leave once")
        `CHK(m_valid === 1'b0, "release: the slice must be empty")

        // 5. m_ready low for one cycle and for several, with a continuous stream.
        a0      = acc;
        d0      = del;
        pat     = 32'b1011_0001_1110_0101_0000_1101_1001_0111;
        s_valid = 1'b1;
        dctr    = dctr + 1'b1;
        s_data  = dctr;
        for (i = 0; i < 32; i = i + 1) begin
            m_ready = pat[0];
            pat     = pat >> 1;
            step;
            if (last_s_fire) begin
                dctr   = dctr + 1'b1;
                s_data = dctr;
            end
        end
        drain;
        `CHK(acc - a0 == del - d0, "pattern: every accepted beat delivered once")

        // 6. Random traffic against the model in four phases, ending in a drain.
        for (k = 0; k < 4; k = k + 1) begin
            case (k)
                0:       begin sv_th = 8'd200; mr_th = 8'd200; end
                1:       begin sv_th = 8'd230; mr_th = 8'd64;  end
                2:       begin sv_th = 8'd64;  mr_th = 8'd230; end
                default: begin sv_th = 8'd128; mr_th = 8'd128; end
            endcase
            for (i = 0; i < 750; i = i + 1) begin
                r       = $random;
                s_valid = (r[7:0] < sv_th);
                m_ready = (r[15:8] < mr_th);
                s_data  = r[16 +: WIDTH];
                step;
            end
        end
        drain;

        // 7. Reset with two beats held.
        m_ready = 1'b0;
        s_valid = 1'b1;
        for (i = 0; i < 3; i = i + 1) begin
            dctr   = dctr + 1'b1;
            s_data = dctr;
            step;
        end
        `CHK(count == 2, "reset held: the model must hold two beats")
        `CHK(m_valid === 1'b1, "reset held: m_valid must be high before reset")
        `CHK(s_ready === 1'b0, "reset held: s_ready must be low before reset")
        rst_n   = 1'b0;
        m_ready = 1'b1;
        s_valid = 1'b1;
        step;
        `CHK(m_valid === 1'b0, "reset held: m_valid must be low after reset")
        `CHK(s_ready === 1'b1, "reset held: s_ready must be high after reset")
        rst_n   = 1'b1;
        s_valid = 1'b0;
        step;
        step;
        `CHK(m_valid === 1'b0, "reset held: no dropped beat may reappear")

        // 8. Random traffic with resets during traffic.
        sv_th = 8'd180;
        mr_th = 8'd150;
        for (i = 0; i < 1000; i = i + 1) begin
            r       = $random;
            s_valid = (r[7:0] < sv_th);
            m_ready = (r[15:8] < mr_th);
            s_data  = r[16 +: WIDTH];
            rst_n   = (r[31:24] >= rst_th);
            step;
        end
        drain;

        `CHK(acc == del + dropped, "scoreboard: every accepted beat delivered once or dropped by reset")
        done = 1'b1;
    end
endmodule

`undef CHK
`default_nettype wire
=== END FILE ===
